const states = new Map();
export const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const utc = (us, exact = false) => !Number.isFinite(us) ? 'Not observed' : new Date(Math.floor(us / 1000)).toISOString().slice(11,19) + '.' + String(us % 1000000).padStart(6,'0').slice(0,exact ? 6 : 3);
export const seconds = us => us == null ? 'Not yet observed' : (us / 1000000).toFixed(3) + ' s';
const e = escapeHTML;
export const frameLabel = f => `${f.type}${f.reasonCode != null ? ` · Reason ${f.reasonCode}` : f.statusCode != null ? ` · Status ${f.statusCode}` : ''}${f.retry ? ' · retry' : ''}`;
export function identifyControls(container,prefix){const counts={};container.querySelectorAll('button,input,select,textarea,summary,[tabindex]').forEach((el,index)=>{if(el.id)return;const key=Object.entries(el.dataset).map(([k,v])=>`${k}-${v}`).join('-')||el.name||el.getAttribute('aria-label')||`control-${index}`;const safe=key.replace(/[^a-zA-Z0-9_-]/g,'-');const count=counts[safe]||0;counts[safe]=count+1;el.id=`${prefix}-${safe}-${count}`;});}
export function preserveFocus(container,render){const active=document.activeElement;const id=container.contains(active)?active.id:null;render();if(id){const el=document.getElementById(id);if(el&&!el.disabled)el.focus({preventScroll:true});}}
function color(frame, incident) { return frame.id === incident.anchors.deauth?.id ? 'attention' : frame.id === incident.anchors.association?.id ? 'association' : 'evidence'; }
export function renderInvestigation(container, ctx) {
  const incident = ctx.service.getIncident(ctx.incidentId, ctx.context);
  if (!incident) { container.innerHTML = '<section class="panel empty-state"><h1>No investigation observed at this replay time</h1><p>Advance the capture to reveal evidence as it arrives.</p><button class="btn" data-empty-play>Play capture</button><button class="btn" data-empty-back>Return to Factory</button></section>'; container.querySelector('[data-empty-play]').onclick=()=>ctx.replay.onPlay(); container.querySelector('[data-empty-back]').onclick=ctx.onFactory; return; }
  const state = states.get(incident.id) || {selection:'anchors',source:'all',page:0,question:'',answer:null,answerContext:null}; states.set(incident.id,state);
  if (state.answerContext !== `${ctx.context.mode}:${ctx.context.cutoffUs}:${ctx.context.generation}`) state.answer = null;
  let result = ctx.service.queryEvidence(incident.id,{selection:state.selection,source:state.source,page:state.page,pageSize:10},ctx.context);
  if (state.page && result.rows.length === 0) {state.page=0; result=ctx.service.queryEvidence(incident.id,{selection:state.selection,source:state.source,page:0,pageSize:10},ctx.context);}
  const rows=incident.evidence || [];
  const sources=ctx.service.manifest.sources.map(s=>s.id);
  const channels=ctx.service.manifest.sources.map(s=>s.channel??s.channels?.[0]??'—');
  const timelineEnd = Math.max(incident.openUs + 15000000, ...rows.map(f=>f.timeUs));
  const estimatedTrackWidth = Math.max(160, Math.min(container.clientWidth, 1200) * (container.clientWidth >= 900 ? .60 : .94) - 140);
  const binCount = Math.max(8,Math.min(100,Math.floor(estimatedTrackWidth/22)));
  const bins = new Map();
  for(const frame of rows){const index=Math.min(binCount-1,Math.max(0,Math.floor((frame.timeUs-incident.openUs)/(timelineEnd-incident.openUs)*binCount)));const key=`${frame.source}-${index}`;if(!bins.has(key))bins.set(key,{source:frame.source,index,frames:[]});bins.get(key).frames.push(frame);}
  const activeBin = state.binKey ? bins.get(state.binKey) : null;
  const laneMarks = source => [...bins.entries()].filter(([,bin])=>bin.source===source).map(([key,bin])=>{const frame=bin.frames[0],multiple=bin.frames.length>1;const hasOpening=bin.frames.some(f=>f.id===incident.anchors.deauth?.id),hasAssociation=bin.frames.some(f=>f.id===incident.anchors.association?.id);const tone=hasOpening&&hasAssociation?'ws-mixed-anchor':hasOpening?'attention':hasAssociation?'association':'evidence';const anchorKind=hasOpening&&hasAssociation?' · Contains opening and association anchors':hasOpening?' · Contains opening anchor':hasAssociation?' · Contains association anchor':'';return `<button class="ws-mark ${multiple?`ws-bin ${tone}`:color(frame,incident)} ${state.binKey===key||ctx.selectedFrameId===frame.id?'is-selected':''}" style="left:${(bin.index+.5)/binCount*100}%" ${multiple?`data-bin="${key}" aria-expanded="${state.binKey===key}"`:`data-frame="${e(frame.id)}"`} title="${multiple?`${bin.frames.length} observations · ${utc(frame.timeUs)}–${utc(bin.frames.at(-1).timeUs)} UTC${anchorKind}`:e(frame.id+' · '+frameLabel(frame)+' · '+utc(frame.timeUs))}" aria-label="${multiple?`${source}: ${bin.frames.length} observations between ${utc(frame.timeUs)} and ${utc(bin.frames.at(-1).timeUs)} UTC${anchorKind}. Open grouped events.`:e(frame.id+' '+frameLabel(frame)+' '+utc(frame.timeUs)+' UTC')}">${multiple?bin.frames.length:''}</button>`;}).join('');
  const r=ctx.replay;
  const replay=ctx.context.mode==='capture_replay';
  const seekRange=Math.max(1,r.endUs-r.startUs);
  const anchorCard=(name,key,tone)=>{const frame=incident.anchors[key];return `<button class="ws-phase ${tone}" ${frame ? `data-frame="${e(frame.id)}"` : 'disabled'}><strong>${name}</strong><span>${frame ? e(frame.reasonCode != null ? `Reason ${frame.reasonCode}` : `Status ${frame.statusCode}`) : 'Not observed'}</span><time class="mono">${frame ? utc(frame.timeUs) : 'in available captures'}</time></button>`;};
  container.innerHTML=`<div class="investigation-view">
    <div class="ws-page-heading"><div><button class="ws-link ws-breadcrumb" data-factory>Factory</button><span class="muted"> / </span><span class="mono">${e(incident.id)}</span><h1>Disconnect investigation</h1><p class="mono muted">Client ${e(incident.client)} · ${e(incident.ap)} · ${utc(incident.openUs)} UTC</p></div><div class="ws-statuses"><span class="chip ws-attention">ⓘ Evidence: partial</span><span class="chip">? Cause: unresolved</span></div></div>
    <div class="ws-columns"><div class="ws-main">
      <div class="panel ws-metrics"><button data-selection="anchors"><span class="ws-metric-icon">◷</span><span><strong>${seconds(incident.durationUs)}</strong><small>Deauth → association response</small></span></button><button data-selection="retry"><span class="ws-metric-icon">▤</span><span><strong>${incident.retryCount}${replay ? '<em> observed so far</em>' : ''}</strong><small>Retry-marked probe responses</small></span></button><button data-selection="retry"><span class="ws-metric-icon">⌁</span><span><strong>${incident.viewpoints}</strong><small>Response viewpoints</small></span></button></div>
      <section class="panel ws-sequence"><h2>Protocol progression</h2><div class="ws-phases">${anchorCard('Deauthentication','deauth','attention')}<span class="ws-arrow">→</span><button class="ws-phase evidence" data-selection="probes"><strong>Probe activity</strong><span>${incident.probeCount} client requests</span><span>${incident.probeViewpoints} source viewpoints</span></button><span class="ws-arrow">→</span>${anchorCard('Authentication','auth','evidence')}<span class="ws-arrow">→</span>${anchorCard('Association','association','association')}</div>
      <div class="ws-timeline-heading"><h2>Event timeline <span class="muted">· 8 capture sources</span></h2><div class="ws-legend"><span class="attention">▏Opening</span><span class="evidence">▏Related</span><span class="association">▏Association</span></div></div>
      <div class="ws-timeline" aria-label="Recorded-time event timeline; individual events also available in evidence table">${sources.map((s,i)=>`<div class="ws-lane"><span class="mono">${s} <small>ch ${channels[i]}</small></span><div class="ws-lane-track">${laneMarks(s)}</div></div>`).join('')}<div class="ws-axis"><span>+0 s</span><span>+${((timelineEnd-incident.openUs)/2000000).toFixed(1)} s</span><span>+${((timelineEnd-incident.openUs)/1000000).toFixed(1)} s</span></div></div>
      ${activeBin?`<section class="ws-bin-detail" aria-label="Grouped timeline observations"><div><h3>${activeBin.source} · ${activeBin.frames.length} observations</h3><button class="ws-link" data-close-bin aria-label="Close grouped timeline observations">Close ×</button></div><p>${utc(activeBin.frames[0].timeUs)}–${utc(activeBin.frames.at(-1).timeUs)} UTC · Exact membership</p><ul>${activeBin.frames.map(frame=>`<li><button class="ws-link" data-frame="${e(frame.id)}"><span class="mono">${e(frame.id)} · ${utc(frame.timeUs,true)}</span><span>${e(frameLabel(frame))} ↗</span></button></li>`).join('')}</ul></section>`:''}
      <p class="ws-notice">ⓘ Cross-source clock alignment unverified. Positions use recorded timestamps.</p>
      <div class="ws-playback"><button class="btn ws-play" data-play aria-label="${replay&&r.playing?'Pause capture':'Play capture'}">${replay&&r.playing?'Ⅱ':'▶'}</button><span class="mono ws-play-time">${replay?utc(r.cursorUs):'Historical review'}</span><input aria-label="Replay position" data-seek type="range" min="0" max="${seekRange}" step="100000" value="${Math.max(0,Math.min(seekRange,r.cursorUs-r.startUs))}">${[1,5,20].map(speed=>`<button class="btn ws-speed ${r.speed===speed?'is-active':''}" data-speed="${speed}" aria-pressed="${r.speed===speed}">${speed}×</button>`).join('')}<button class="btn" data-restart title="Restart capture replay">↺<span class="sr-only"> Restart replay</span></button></div><div class="ws-replay-extra"><button class="ws-link" data-previous>← Previous event</button><button class="ws-link" data-next>Next event →</button><button class="ws-link" data-mode>${replay?'Return to historical review':'Enter capture replay'}</button></div>
      </section>
      <section class="panel ws-evidence"><div class="ws-evidence-heading"><h2>Evidence</h2><label class="ws-source-label">Source <select data-source aria-label="Filter evidence by source"><option value="all">All sources</option>${sources.map(s=>`<option ${state.source===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="ws-tabs" role="group" aria-label="Evidence selections">${[['anchors','Protocol anchors'],['retry','Retry responses'],['probes','Client probes'],['all','All episode context']].map(([id,label])=>`<button class="${state.selection===id?'is-active':''}" data-selection="${id}" aria-pressed="${state.selection===id}">${label}</button>`).join('')}</div><div class="ws-table-scroll" tabindex="0" role="region" aria-label="Evidence observations"><table><thead><tr><th>Frame</th><th>Recorded UTC</th><th>Event</th><th>Source</th><th>Channel</th><th>Signal</th></tr></thead><tbody>${result.rows.map(f=>`<tr class="${ctx.selectedFrameId===f.id?'is-selected':''}"><td><button class="ws-link mono" data-frame="${e(f.id)}">${e(f.id)}</button></td><td class="mono">${utc(f.timeUs)}</td><td class="${color(f,incident)}">${e(frameLabel(f))}</td><td>${e(f.source)}</td><td>${e(f.channel ?? '—')}</td><td>${f.signal == null?'Unavailable':`${f.signal} dBm`}</td></tr>`).join('') || '<tr><td colspan="6" class="ws-empty">No observations match this selection at the current cutoff.</td></tr>'}</tbody></table></div><div class="ws-pagination"><span>Showing ${result.total?state.page*10+1:0}–${Math.min((state.page+1)*10,result.total)} of ${result.total} matching observations</span><div><button class="btn" data-page="-1" ${state.page===0?'disabled':''}>Previous</button><button class="btn" data-page="1" ${(state.page+1)*10>=result.total?'disabled':''}>Next</button></div></div><details class="ws-definition"><summary>Selection definition</summary><p>${e(result.predicate || 'Exact visible incident membership in recorded timestamp order.')}</p></details></section>
    </div><aside class="panel ws-interpretation"><section><h2><span>▤</span> What the evidence establishes</h2><p>${incident.anchors.association?'A deauthentication frame from the AP-addressed transmitter preceded a successful association response to the same BSSID.':'A deauthentication frame from the AP-addressed transmitter is observed. A later association response has not yet been observed in this view.'}</p><button class="ws-link" data-frame="${e(incident.anchors.deauth.id)}">Inspect opening evidence ↗</button></section><section><h2><span>?</span> What remains unknown</h2><p>The AP decision requires controller evidence. Association does not establish application recovery or enterprise authentication success.</p><p class="muted">Source health and cross-source clock alignment are unverified.</p></section><section><h2><span>↗</span> Related evidence</h2>${Object.entries(incident.anchors).filter(([,f])=>f).map(([key,f])=>`<button class="ws-related" data-frame="${e(f.id)}"><span><strong>${e(frameLabel(f))}</strong><small>${e(f.id)} · ${utc(f.timeUs)} UTC</small></span><span>Open ↗</span></button>`).join('')}<button class="ws-related" data-selection="retry"><span><strong>Probe responses · retry-marked</strong><small>${incident.retryCount} observations · ${incident.viewpoints} source viewpoints</small></span><span>View →</span></button></section><section class="ws-questions"><div class="ws-evidence-heading"><h2>Ask about this sequence</h2><span class="ws-evidence-badge">Evidence-guided</span></div><div class="ws-suggestions"><button data-question="What does the duration measure?">Explain duration</button><button data-question="What evidence is needed next?">Next evidence</button></div><form data-question-form><label class="sr-only" for="ws-question">Question about this sequence</label><input id="ws-question" data-question-input value="${e(state.question)}" placeholder="What does reason code 23 establish?" autocomplete="off"><button aria-label="Ask question" type="submit">↗</button></form>${state.answer?`<div class="ws-answer" role="status"><p>${e(state.answer.text)}</p><small>Snapshot · ${ctx.context.mode==='capture_replay'?utc(ctx.context.cutoffUs)+' UTC':'Historical review'}</small><div>${(state.answer.citations||[]).map(id=>`<button class="ws-link mono" data-frame="${e(id)}">${e(id)} ↗</button>`).join('')}</div></div>`:''}</section><button class="btn btn-primary ws-action" data-action>Open action brief <span>→</span></button></aside></div></div>`;
  identifyControls(container,'ws');
  const redraw=()=>ctx.refresh?ctx.refresh():preserveFocus(container,()=>renderInvestigation(container,ctx));
  container.querySelector('[data-factory]').onclick=ctx.onFactory;
  container.querySelectorAll('[data-frame]').forEach(button=>button.onclick=()=>ctx.onFrame(button.dataset.frame));
  container.querySelectorAll('[data-bin]').forEach(button=>button.onclick=()=>{state.binKey=state.binKey===button.dataset.bin?null:button.dataset.bin;redraw();});
  container.querySelector('[data-close-bin]')?.addEventListener('click',()=>{const key=state.binKey;state.binKey=null;redraw();container.querySelector(`[data-bin="${key}"]`)?.focus({preventScroll:true});});
  container.querySelectorAll('[data-selection]').forEach(button=>button.onclick=()=>{state.selection=button.dataset.selection;state.page=0;redraw();});
  container.querySelector('[data-source]').onchange=event=>{state.source=event.target.value;state.page=0;redraw();};
  container.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{state.page+=Number(button.dataset.page);redraw();});
  container.querySelector('[data-play]').onclick=()=>replay&&r.playing?r.onPause():r.onPlay();
  container.querySelector('[data-seek]').onchange=event=>r.onSeek(r.startUs+Number(event.target.value));
  container.querySelectorAll('[data-speed]').forEach(button=>button.onclick=()=>r.onSpeed(Number(button.dataset.speed)));
  container.querySelector('[data-restart]').onclick=r.onRestart;
  container.querySelector('[data-mode]').onclick=()=>r.onMode(replay?'historical_review':'capture_replay');
  const seekEvent=direction=>{const current=ctx.selectedFrameId?rows.find(f=>f.id===ctx.selectedFrameId)?.timeUs:Number.isFinite(r.cursorUs)?r.cursorUs:incident.openUs-1;const ordered=[...rows].sort((a,b)=>a.timeUs-b.timeUs);const frame=direction>0?ordered.find(f=>f.timeUs>(current??incident.openUs)):ordered.reverse().find(f=>f.timeUs<(current??incident.openUs));if(frame){r.onSeek(frame.timeUs);ctx.onFrame(frame.id);}else ctx.notify('No further visible event in this direction.');};
  container.querySelector('[data-previous]').onclick=()=>seekEvent(-1);
  container.querySelector('[data-next]').onclick=()=>seekEvent(1);
  container.querySelector('[data-action]').onclick=ctx.onAction;
  container.querySelector('[data-question-input]').oninput=event=>state.question=event.target.value;
  const ask=question=>{if(!question.trim())return;state.question=question;state.answer=ctx.service.answer(incident.id,question,ctx.context);state.answerContext=`${ctx.context.mode}:${ctx.context.cutoffUs}:${ctx.context.generation}`;redraw();};
  container.querySelector('[data-question-form]').onsubmit=event=>{event.preventDefault();ask(state.question);};
  container.querySelectorAll('[data-question]').forEach(button=>button.onclick=()=>ask(button.dataset.question));
}
